create table if not exists public.team_access ( profile_id uuid primary key references public.profiles (id) on delete cascade, contracts boolean not null, logins boolean not null, money boolean not null, updated_by uuid references public.profiles (id) on delete set null, updated_at timestamptz not null default now() ); alter table public.team_access enable row level security; drop policy if exists "team_access: ceo" on public.team_access; create policy "team_access: ceo" on public.team_access for all using (public.is_ceo_role()) with check (public.is_ceo_role()); drop policy if exists "team_access: read own" on public.team_access; create policy "team_access: read own" on public.team_access for select using (profile_id = auth.uid()); create or replace function public.staff_can(area text) returns boolean language sql stable security definer set search_path = public as $$ select public.current_role() = 'staff' and coalesce( (select case area when 'contracts' then a.contracts when 'logins' then a.logins when 'money' then a.money end from public.team_access a where a.profile_id = auth.uid()), area in ('contracts', 'logins') ); $$; revoke all on function public.staff_can(text) from public; grant execute on function public.staff_can(text) to authenticated; drop policy if exists "documents: staff assigned" on public.documents; create policy "documents: staff assigned" on public.documents for all using (public.current_role() = 'staff' and public.is_assigned_staff(client_id) and public.staff_can('contracts')) with check (public.current_role() = 'staff' and public.is_assigned_staff(client_id) and public.staff_can('contracts')); drop policy if exists "client-documents: staff assigned" on storage.objects; create policy "client-documents: staff assigned" on storage.objects for all using ( bucket_id = 'client-documents' and public.current_role() = 'staff' and public.is_assigned_staff(public.storage_path_client_id(name)) and public.staff_can('contracts') ) with check ( bucket_id = 'client-documents' and public.current_role() = 'staff' and public.is_assigned_staff(public.storage_path_client_id(name)) and public.staff_can('contracts') ); do $$ begin if to_regclass('public.client_credentials') is not null then execute 'drop policy if exists "client_credentials: staff assigned" on public.client_credentials'; execute $p$create policy "client_credentials: staff assigned" on public.client_credentials for all using (public.current_role() = 'staff' and public.is_assigned_staff(client_id) and public.staff_can('logins')) with check (public.current_role() = 'staff' and public.is_assigned_staff(client_id) and public.staff_can('logins'))$p$; end if; end $$; drop policy if exists "invoices: staff read when allowed" on public.invoices; create policy "invoices: staff read when allowed" on public.invoices for select using (public.current_role() = 'staff' and public.is_assigned_staff(client_id) and public.staff_can('money')); do $$ begin if to_regclass('public.client_accounts') is not null then execute 'drop policy if exists "client_accounts: staff read when allowed" on public.client_accounts'; execute $p$create policy "client_accounts: staff read when allowed" on public.client_accounts for select using (public.current_role() = 'staff' and public.is_assigned_staff(client_id) and public.staff_can('money'))$p$; end if; end $$; drop policy if exists "client_activity: staff assigned" on public.client_activity; create policy "client_activity: staff assigned" on public.client_activity for all using ( public.current_role() = 'staff' and public.is_assigned_staff(client_id) and (kind !~ '^(invoice|finance|payment|billing|account)' or public.staff_can('money')) and (kind !~ '^document' or public.staff_can('contracts')) and (kind !~ '^credential' or public.staff_can('logins')) ) with check (public.current_role() = 'staff' and public.is_assigned_staff(client_id)); drop policy if exists "client_activity: videographer read assigned" on public.client_activity; create policy "client_activity: videographer read assigned" on public.client_activity for select using ( public.current_role() = 'videographer' and public.is_assigned_staff(client_id) and kind !~ '^(invoice|document|finance|payment|billing|credential|account)' );
